package ir.mhdolatabadi.atid.data

/**
 * A single religious text entry shown in the "متون مذهبی" tab.
 *
 * The Arabic bodies below are reproduced from memory (this build environment has no access to
 * reference sites to verify them against). They cover the well-known core of each text rather
 * than every optional passage, and should be checked against a trusted copy (e.g. Mafatih
 * al-Jinan) before being treated as authoritative.
 */
data class ReligiousText(
    val id: String,
    val title: String,
    val subtitle: String,
    val note: String,
    val body: String
)

object ReligiousTexts {

    val ZIYARAT_ASHURA = ReligiousText(
        id = "ziyarat_ashura",
        title = "زیارت عاشورا",
        subtitle = "زیارت امام حسین علیه‌السلام",
        note = "متن زیر بخش شناخته‌شده و پرکاربرد زیارت است؛ پیش از استفاده، آن را با نسخه‌ای معتبر مانند مفاتیح‌الجنان مطابقت دهید.",
        body = """
بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِیمِ

اَلسَّلامُ عَلَیْکَ یَا أَبَا عَبْدِ اللَّهِ، اَلسَّلامُ عَلَیْکَ یَا بْنَ رَسُولِ اللَّهِ، اَلسَّلامُ عَلَیْکَ یَا خِیَرَةَ اللَّهِ وَابْنَ خِیَرَتِهِ، اَلسَّلامُ عَلَیْکَ یَا بْنَ أَمِیرِ الْمُؤْمِنِینَ وَابْنَ سَیِّدِ الْوَصِیِّینَ، اَلسَّلامُ عَلَیْکَ یَا بْنَ فَاطِمَةَ سَیِّدَةِ نِسَاءِ الْعَالَمِینَ، اَلسَّلامُ عَلَیْکَ یَا ثَارَ اللَّهِ وَابْنَ ثَارِهِ وَالْوِتْرَ الْمَوْتُورَ، اَلسَّلامُ عَلَیْکَ وَعَلَی الْأَرْوَاحِ الَّتِی حَلَّتْ بِفِنَائِکَ، عَلَیْکُمْ مِنِّی جَمِیعًا سَلامُ اللَّهِ أَبَدًا مَا بَقِیتُ وَبَقِیَ اللَّیْلُ وَالنَّهَارُ.

یَا أَبَا عَبْدِ اللَّهِ، لَقَدْ عَظُمَتِ الرَّزِیَّةُ وَجَلَّتْ وَعَظُمَتِ الْمُصِیبَةُ بِکَ عَلَیْنَا وَعَلَی جَمِیعِ أَهْلِ الْإِسْلامِ، وَجَلَّتْ وَعَظُمَتْ مُصِیبَتُکَ فِی السَّمَاوَاتِ عَلَی جَمِیعِ أَهْلِ السَّمَاوَاتِ، فَلَعَنَ اللَّهُ أُمَّةً أَسَّسَتْ أَسَاسَ الظُّلْمِ وَالْجَوْرِ عَلَیْکُمْ أَهْلَ الْبَیْتِ، وَلَعَنَ اللَّهُ أُمَّةً دَفَعَتْکُمْ عَنْ مَقَامِکُمْ وَأَزَالَتْکُمْ عَنْ مَرَاتِبِکُمُ الَّتِی رَتَّبَکُمُ اللَّهُ فِیهَا، وَلَعَنَ اللَّهُ أُمَّةً قَتَلَتْکُمْ، وَلَعَنَ اللَّهُ الْمُمَهِّدِینَ لَهُمْ بِالتَّمْکِینِ مِنْ قِتَالِکُمْ، فَأَنَا إِلَی اللَّهِ مِنْهُمْ بَرِیءٌ وَمِنْ أَشْیَاعِهِمْ وَأَتْبَاعِهِمْ وَأَوْلِیَائِهِمْ بَرِیءٌ، یَا أَبَا عَبْدِ اللَّهِ إِنِّی سِلْمٌ لِمَنْ سَالَمَکُمْ وَحَرْبٌ لِمَنْ حَارَبَکُمْ إِلَی یَوْمِ الْقِیَامَةِ، وَلَعَنَ اللَّهُ آلَ زِیَادٍ وَآلَ مَرْوَانَ، وَلَعَنَ اللَّهُ بَنِی أُمَیَّةَ قَاطِبَةً، وَلَعَنَ اللَّهُ ابْنَ مَرْجَانَةَ، وَلَعَنَ اللَّهُ عُمَرَ بْنَ سَعْدٍ، وَلَعَنَ اللَّهُ شِمْرًا، وَلَعَنَ اللَّهُ أُمَّةً أَسْرَجَتْ وَأَلْجَمَتْ وَتَنَقَّبَتْ لِقِتَالِکَ، بِأَبِی أَنْتَ وَأُمِّی، لَقَدْ عَظُمَ مُصَابِی بِکَ، فَأَسْأَلُ اللَّهَ الَّذِی أَکْرَمَ مَقَامَکَ وَأَکْرَمَنِی بِکَ أَنْ یَرْزُقَنِی طَلَبَ ثَارِکَ مَعَ إِمَامٍ مَنْصُورٍ مِنْ أَهْلِ بَیْتِ مُحَمَّدٍ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ.

اَللَّهُمَّ اجْعَلْنِی عِنْدَکَ وَجِیهًا بِالْحُسَیْنِ عَلَیْهِ السَّلامُ فِی الدُّنْیَا وَالْآخِرَةِ.

یَا أَبَا عَبْدِ اللَّهِ إِنِّی أَتَقَرَّبُ إِلَی اللَّهِ وَإِلَی رَسُولِهِ وَإِلَی أَمِیرِ الْمُؤْمِنِینَ وَإِلَی فَاطِمَةَ وَإِلَی الْحَسَنِ وَإِلَیْکَ بِمُوَالاتِکَ وَبِالْبَرَاءَةِ مِمَّنْ أَسَّسَ أَسَاسَ ذَلِکَ وَبَنَی عَلَیْهِ بُنْیَانَهُ، وَجَرَی فِی ظُلْمِهِ وَجَوْرِهِ عَلَیْکُمْ وَعَلَی أَشْیَاعِکُمْ، بَرِئْتُ إِلَی اللَّهِ وَإِلَیْکُمْ مِنْهُمْ وَتَقَرَّبْتُ إِلَی اللَّهِ ثُمَّ إِلَیْکُمْ بِمُوَالاتِکُمْ وَمُوَالاةِ وَلِیِّکُمْ، وَبِالْبَرَاءَةِ مِنْ أَعْدَائِکُمْ وَالنَّاصِبِینَ لَکُمُ الْحَرْبَ، وَبِالْبَرَاءَةِ مِنْ أَشْیَاعِهِمْ وَأَتْبَاعِهِمْ، إِنِّی بَرِیءٌ إِلَی اللَّهِ وَإِلَیْکُمْ مِنْهُمْ وَأَتَقَرَّبُ إِلَی اللَّهِ ثُمَّ إِلَیْکُمْ بِمُوَالاتِکُمْ.

(سپس صد بار گفته می‌شود:)
اَللَّهُمَّ الْعَنْ أَوَّلَ ظَالِمٍ ظَلَمَ حَقَّ مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَآخِرَ تَابِعٍ لَهُ عَلَی ذَلِکَ، اَللَّهُمَّ الْعَنِ الْعِصَابَةَ الَّتِی جَاهَدَتِ الْحُسَیْنَ وَشَایَعَتْ وَبَایَعَتْ وَتَابَعَتْ عَلَی قَتْلِهِ، اَللَّهُمَّ الْعَنْهُمْ جَمِیعًا.

(سپس صد بار گفته می‌شود:)
اَلسَّلامُ عَلَیْکَ یَا أَبَا عَبْدِ اللَّهِ وَعَلَی الْأَرْوَاحِ الَّتِی حَلَّتْ بِفِنَائِکَ، عَلَیْکَ مِنِّی سَلامُ اللَّهِ أَبَدًا مَا بَقِیتُ وَبَقِیَ اللَّیْلُ وَالنَّهَارُ، وَلا جَعَلَهُ اللَّهُ آخِرَ الْعَهْدِ مِنِّی لِزِیَارَتِکُمْ، اَلسَّلامُ عَلَی الْحُسَیْنِ وَعَلَی عَلِیِّ بْنِ الْحُسَیْنِ وَعَلَی أَوْلادِ الْحُسَیْنِ وَعَلَی أَصْحَابِ الْحُسَیْنِ.

اَللَّهُمَّ خُصَّ أَنْتَ أَوَّلَ ظَالِمٍ بِاللَّعْنِ مِنِّی، وَابْدَأْ بِهِ أَوَّلاً، ثُمَّ الثَّانِیَ وَالثَّالِثَ وَالرَّابِعَ، اَللَّهُمَّ الْعَنْ یَزِیدَ خَامِسًا، وَالْعَنْ عُبَیْدَ اللَّهِ بْنَ زِیَادٍ وَابْنَ مَرْجَانَةَ وَعُمَرَ بْنَ سَعْدٍ وَشِمْرًا وَآلَ أَبِی سُفْیَانَ وَآلَ زِیَادٍ وَآلَ مَرْوَانَ إِلَی یَوْمِ الْقِیَامَةِ.

اَللَّهُمَّ إِنِّی أَتَقَرَّبُ إِلَیْکَ فِی هَذَا الْیَوْمِ وَفِی مَوْقِفِی هَذَا وَأَیَّامِ حَیَاتِی بِالْبَرَاءَةِ مِنْهُمْ وَاللَّعْنَةِ عَلَیْهِمْ، وَبِالْمُوَالاةِ لِنَبِیِّکَ وَآلِ نَبِیِّکَ عَلَیْهِ وَعَلَیْهِمُ السَّلامُ.

اَللَّهُمَّ إِنَّ هَذَا یَوْمٌ تَبَرَّکَتْ بِهِ بَنُو أُمَیَّةَ، وَابْنُ آکِلَةِ الْأَکْبَادِ، الطَّلِیقُ ابْنُ الطَّلِیقِ، الَّذِی اتَّخَذَهُ الطُّلَقَاءُ وَأَبْنَاءُ الطُّلَقَاءِ عِیدًا، وَجَعَلُوهُ مَوْسِمًا یَجْتَمِعُونَ فِیهِ، یَتَبَرَّکُونَ بِهِ بِقَتْلِ الْحُسَیْنِ عَلَیْهِ السَّلامُ. اَللَّهُمَّ فَضَاعِفْ عَلَی ابْنِ آکِلَةِ الْأَکْبَادِ لَعْنَکَ وَعَذَابَکَ. اَللَّهُمَّ إِنَّ هَذَا یَوْمٌ فَرِحَتْ بِهِ آلُ زِیَادٍ وَآلُ مَرْوَانَ بِقَتْلِهِمُ الْحُسَیْنَ صَلَوَاتُ اللَّهِ عَلَیْهِ، اَللَّهُمَّ فَضَاعِفْ لَعْنَکَ وَعَذَابَکَ عَلَیْهِمْ.

اَللَّهُمَّ ارْحَمْ تِلْکَ الْأَبْدَانَ الَّتِی بُلِیَتْ وَتَقَطَّعَتْ أَعْضَاؤُهَا فِینَا، وَأَرْوَاحًا اجْتَمَعَتْ عَلَی نَصْرِنَا فَاسْتُشْهِدَتْ، اَللَّهُمَّ اجْعَلْنِی مَعَکَ فِی الدُّنْیَا وَالْآخِرَةِ.
        """.trimIndent()
    )

    val SAHIFA_DUA_7 = ReligiousText(
        id = "sahifa_dua_7",
        title = "دعای هفتم صحیفه سجادیه",
        subtitle = "دعای امام سجاد علیه‌السلام هنگام گرفتاری و اندوه",
        note = "متن زیر بخش آغازین و شناخته‌شده‌ی دعاست، نه لزوماً کل ده فراز آن؛ برای متن کامل به نسخه‌ای معتبر از صحیفه سجادیه مراجعه کنید.",
        body = """
یَا مَنْ تُحَلُّ بِهِ عُقَدُ الْمَکَارِهِ، وَیَا مَنْ یُفْثَأُ بِهِ حَدُّ الشَّدَائِدِ، وَیَا مَنْ یُلْتَمَسُ مِنْهُ الْمَخْرَجُ إِلَی رَوْحِ الْفَرَجِ، ذَلَّتْ لِقُدْرَتِکَ الصِّعَابُ، وَتَسَبَّبَتْ بِلُطْفِکَ الْأَسْبَابُ، وَجَرَی بِقُدْرَتِکَ الْقَضَاءُ، وَمَضَتْ عَلَی إِرَادَتِکَ الْأَشْیَاءُ، فَهِیَ بِمَشِیَّتِکَ دُونَ قَوْلِکَ مُؤْتَمِرَةٌ، وَبِإِرَادَتِکَ دُونَ نَهْیِکَ مُنْزَجِرَةٌ.

أَنْتَ الْمَدْعُوُّ لِلْمُهِمَّاتِ، وَأَنْتَ الْمَفْزَعُ فِی الْمُلِمَّاتِ، لا یَنْدَفِعُ مِنْهَا إِلاَّ مَا دَفَعْتَ، وَلا یَنْکَشِفُ مِنْهَا إِلاَّ مَا کَشَفْتَ، وَقَدْ نَزَلَ بِی یَا رَبِّ مَا قَدْ تَکَأَّدَنِی ثِقْلُهُ، وَأَلَمَّ بِی مَا قَدْ بَهَظَنِی حَمْلُهُ، وَبِقُدْرَتِکَ أَوْرَدْتَهُ عَلَیَّ، وَبِسُلْطَانِکَ وَجَّهْتَهُ إِلَیَّ، فَلا مُصْدِرَ لِمَا أَوْرَدْتَ، وَلا صَارِفَ لِمَا وَجَّهْتَ، وَلا فَاتِحَ لِمَا أَغْلَقْتَ، وَلا مُغْلِقَ لِمَا فَتَحْتَ، وَلا مُیَسِّرَ لِمَا عَسَّرْتَ، وَلا نَاصِرَ لِمَنْ خَذَلْتَ.

فَصَلِّ عَلَی مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَافْتَحِ اللَّهُمَّ لِی بَابَ الْفَرَجِ بِطَوْلِکَ، وَاکْسِرْ عَنِّی سُلْطَانَ الْهَمِّ بِحَوْلِکَ، وَأَنِلْنِی حُسْنَ النَّظَرِ فِیمَا شَکَوْتُ، وَأَذِقْنِی حَلاوَةَ الصُّنْعِ فِیمَا سَأَلْتُ، وَهَبْ لِی مِنْ لَدُنْکَ رَحْمَةً وَفَرَجًا هَنِیئًا، وَاجْعَلْ لِی مِنْ عِنْدِکَ مَخْرَجًا وَحِیًّا، وَلا تَشْغَلْنِی بِالِاهْتِمَامِ عَنْ تَعَاهُدِ فُرُوضِی، وَاسْتِعْمَالِ سُنَّتِی، فَقَدْ ضِقْتُ لِمَا نَزَلَ بِی یَا رَبِّ ذَرْعًا، وَامْتَلَأْتُ بِحَمْلِ مَا حَدَثَ عَلَیَّ هَمًّا، وَأَنْتَ الْقَادِرُ عَلَی کَشْفِ مَا مُنِیتُ بِهِ، وَدَفْعِ مَا وَقَعْتُ فِیهِ، فَافْعَلْ بِی ذَلِکَ وَإِنْ لَمْ أَسْتَوْجِبْهُ مِنْکَ بِمَنِّکَ وَجُودِکَ، یَا وَاسِعَ الْمَغْفِرَةِ، یَا بَاسِطَ الْیَدَیْنِ بِالرَّحْمَةِ، فَوَعِزَّتِکَ یَا سَیِّدِی لا أَجِدُ لِکَرْبِی غَیْرَکَ فَارِجًا، وَلا أَعْرِفُ لِضَیْقِی سِوَاکَ مُفَرِّجًا.
        """.trimIndent()
    )

    val HADITH_KISA = ReligiousText(
        id = "hadith_kisa",
        title = "حدیث کساء",
        subtitle = "روایت فاطمه زهرا سلام‌الله‌علیها",
        note = "متن زیر بازنویسی از حفظ است؛ پیش از استفاده آن را با نسخه‌ای معتبر مطابقت دهید.",
        body = """
بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِیمِ

عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِیِّ قَالَ: قَالَتْ فَاطِمَةُ الزَّهْرَاءُ صَلَوَاتُ اللَّهِ عَلَیْهَا بِنْتُ رَسُولِ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ: دَخَلَ عَلَیَّ أَبِی رَسُولُ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ فِی بَعْضِ الْأَیَّامِ فَقَالَ: السَّلامُ عَلَیْکِ یَا فَاطِمَةُ، فَقُلْتُ: وَعَلَیْکَ السَّلامُ، فَقَالَ: إِنِّی أَجِدُ فِی بَدَنِی ضَعْفًا، فَقُلْتُ: أُعِیذُکَ بِاللَّهِ یَا أَبَتِ مِنَ الضَّعْفِ، فَقَالَ: یَا فَاطِمَةُ ائْتِینِی بِالْکِسَاءِ الْیَمَانِی فَغَطِّینِی بِهِ، فَأَتَیْتُهُ بِالْکِسَاءِ الْیَمَانِی فَغَطَّیْتُهُ بِهِ وَأَنَا أَنْظُرُ إِلَیْهِ وَکَأَنَّ وَجْهَهُ الْقَمَرُ لَیْلَةَ الْبَدْرِ.

فَلَمْ یَلْبَثْ أَنْ أَقْبَلَ وَلَدِیَ الْحَسَنُ عَلَیْهِ السَّلامُ وَقَالَ: السَّلامُ عَلَیْکِ یَا أُمَّاهُ، فَقُلْتُ: وَعَلَیْکَ السَّلامُ یَا قُرَّةَ عَیْنِی وَثَمَرَةَ فُؤَادِی، فَقَالَ: یَا أُمَّاهُ إِنِّی أَشُمُّ عِنْدَکِ رَائِحَةً طَیِّبَةً کَأَنَّهَا رَائِحَةُ جَدِّی رَسُولِ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ، فَقُلْتُ: نَعَمْ إِنَّ جَدَّکَ تَحْتَ الْکِسَاءِ، فَأَقْبَلَ الْحَسَنُ نَحْوَ الْکِسَاءِ وَقَالَ: السَّلامُ عَلَیْکَ یَا جَدَّاهُ أَتَأْذَنُ لِی أَنْ أَکُونَ مَعَکَ تَحْتَ الْکِسَاءِ؟ فَقَالَ: وَعَلَیْکَ السَّلامُ یَا وَلَدِی وَیَا صَاحِبَ حَوْضِی، قَدْ أَذِنْتُ لَکَ، فَدَخَلَ مَعَهُ تَحْتَ الْکِسَاءِ.

فَلَمْ یَلْبَثْ أَنْ أَقْبَلَ وَلَدِیَ الْحُسَیْنُ عَلَیْهِ السَّلامُ وَقَالَ: السَّلامُ عَلَیْکِ یَا أُمَّاهُ، فَقُلْتُ: وَعَلَیْکَ السَّلامُ یَا وَلَدِی وَیَا قُرَّةَ عَیْنِی وَثَمَرَةَ فُؤَادِی، فَقَالَ: یَا أُمَّاهُ إِنِّی أَشُمُّ عِنْدَکِ رَائِحَةً طَیِّبَةً کَأَنَّهَا رَائِحَةُ جَدِّی رَسُولِ اللَّهِ، فَقُلْتُ: نَعَمْ إِنَّ جَدَّکَ وَأَخَاکَ تَحْتَ الْکِسَاءِ، فَأَقْبَلَ نَحْوَ الْکِسَاءِ وَقَالَ: السَّلامُ عَلَیْکَ یَا جَدَّاهُ أَتَأْذَنُ لِی أَنْ أَکُونَ مَعَکُمَا تَحْتَ الْکِسَاءِ؟ فَقَالَ: وَعَلَیْکَ السَّلامُ یَا وَلَدِی وَیَا شَافِعَ أُمَّتِی، قَدْ أَذِنْتُ لَکَ، فَدَخَلَ مَعَهُمَا تَحْتَ الْکِسَاءِ.

فَلَمْ یَلْبَثْ أَنْ أَقْبَلَ أَبُو الْحَسَنِ عَلِیُّ بْنُ أَبِی طَالِبٍ عَلَیْهِ السَّلامُ وَقَالَ: السَّلامُ عَلَیْکِ یَا بِنْتَ رَسُولِ اللَّهِ، فَقُلْتُ: وَعَلَیْکَ السَّلامُ یَا أَبَا الْحَسَنِ، فَقَالَ: یَا فَاطِمَةُ إِنِّی أَشُمُّ عِنْدَکِ رَائِحَةً طَیِّبَةً کَأَنَّهَا رَائِحَةُ أَخِی وَابْنِ عَمِّی رَسُولِ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ، فَقُلْتُ: نَعَمْ هَا هُوَ مَعَ وَلَدَیْکَ تَحْتَ الْکِسَاءِ، فَأَقْبَلَ نَحْوَ الْکِسَاءِ وَقَالَ: السَّلامُ عَلَیْکَ یَا رَسُولَ اللَّهِ أَتَأْذَنُ لِی أَنْ أَکُونَ مَعَکُمْ تَحْتَ الْکِسَاءِ؟ فَقَالَ: وَعَلَیْکَ السَّلامُ یَا أَخِی وَیَا وَصِیِّی وَخَلِیفَتِی وَصَاحِبَ لِوَائِی، قَدْ أَذِنْتُ لَکَ، فَدَخَلَ مَعَهُمْ تَحْتَ الْکِسَاءِ.

ثُمَّ أَقْبَلْتُ أَنَا نَحْوَ الْکِسَاءِ وَقُلْتُ: السَّلامُ عَلَیْکَ یَا أَبَتَاهُ أَتَأْذَنُ لِی أَنْ أَکُونَ مَعَکُمْ تَحْتَ الْکِسَاءِ؟ فَقَالَ: وَعَلَیْکِ السَّلامُ یَا بِنْتِی وَیَا بَضْعَتِی، قَدْ أَذِنْتُ لَکِ، فَدَخَلْتُ مَعَهُمْ تَحْتَ الْکِسَاءِ.

فَلَمَّا اکْتَمَلْنَا جَمِیعًا تَحْتَ الْکِسَاءِ أَخَذَ أَبِی رَسُولُ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ بِطَرَفَیِ الْکِسَاءِ وَأَوْمَأَ بِیَدِهِ الْیُمْنَی إِلَی السَّمَاءِ وَقَالَ: اللَّهُمَّ إِنَّ هَؤُلاءِ أَهْلُ بَیْتِی وَخَاصَّتِی وَحَامَّتِی، لَحْمُهُمْ لَحْمِی، وَدَمُهُمْ دَمِی، یُؤْلِمُنِی مَا یُؤْلِمُهُمْ، وَیَحْزُنُنِی مَا یَحْزُنُهُمْ، أَنَا حَرْبٌ لِمَنْ حَارَبَهُمْ، وَسِلْمٌ لِمَنْ سَالَمَهُمْ، وَعَدُوٌّ لِمَنْ عَادَاهُمْ، وَمُحِبٌّ لِمَنْ أَحَبَّهُمْ، إِنَّهُمْ مِنِّی وَأَنَا مِنْهُمْ، فَاجْعَلْ صَلَوَاتِکَ وَبَرَکَاتِکَ وَرَحْمَتَکَ وَغُفْرَانَکَ وَرِضْوَانَکَ عَلَیَّ وَعَلَیْهِمْ، وَأَذْهِبْ عَنْهُمُ الرِّجْسَ وَطَهِّرْهُمْ تَطْهِیرًا.

فَقَالَ اللَّهُ عَزَّ وَجَلَّ: یَا مَلائِکَتِی، یَا سُکَّانَ سَمَاوَاتِی، إِنِّی مَا خَلَقْتُ سَمَاءً مَبْنِیَّةً، وَلا أَرْضًا مَدْحِیَّةً، وَلا قَمَرًا مُنِیرًا، وَلا شَمْسًا مُضِیئَةً، وَلا فَلَکًا یَدُورُ، وَلا بَحْرًا یَجْرِی، وَلا فُلْکًا یَسْرِی، إِلاَّ فِی مَحَبَّةِ هَؤُلاءِ الْخَمْسَةِ الَّذِینَ هُمْ تَحْتَ الْکِسَاءِ.

فَقَالَ الْأَمِینُ جِبْرَائِیلُ: یَا رَبِّ وَمَنْ تَحْتَ الْکِسَاءِ؟ فَقَالَ عَزَّ وَجَلَّ: هُمْ أَهْلُ بَیْتِ النُّبُوَّةِ، وَمَعْدِنُ الرِّسَالَةِ، هُمْ فَاطِمَةُ وَأَبُوهَا وَبَعْلُهَا وَبَنُوهَا. فَقَالَ جِبْرَائِیلُ: یَا رَبِّ أَتَأْذَنُ لِی أَنْ أَهْبِطَ إِلَی الْأَرْضِ لِأَکُونَ مَعَهُمْ سَادِسًا؟ فَقَالَ اللَّهُ عَزَّ وَجَلَّ: نَعَمْ قَدْ أَذِنْتُ لَکَ.

فَهَبَطَ الْأَمِینُ جِبْرَائِیلُ فَقَالَ: السَّلامُ عَلَیْکَ یَا رَسُولَ اللَّهِ، الْعَلِیُّ الْأَعْلَی یُقْرِئُکَ السَّلامَ وَیَقُولُ لَکَ: إِنِّی مَا خَلَقْتُ سَمَاءً مَبْنِیَّةً وَلا أَرْضًا مَدْحِیَّةً إِلاَّ فِی مَحَبَّتِکُمْ، وَقَدْ أَمَرَنِی أَنْ أَکُونَ مَعَکُمْ سَادِسًا. فَقَالَ رَسُولُ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ: وَعَلَیْکَ السَّلامُ یَا أَمِینَ وَحْیِ اللَّهِ، نَعَمْ قَدْ أَذِنْتُ لَکَ، فَدَخَلَ جِبْرَائِیلُ مَعَهُمْ تَحْتَ الْکِسَاءِ.

فَقَالَ عَلِیٌّ عَلَیْهِ السَّلامُ: یَا رَسُولَ اللَّهِ أَخْبِرْنِی مَا لِجُلُوسِنَا هَذَا تَحْتَ الْکِسَاءِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ: وَالَّذِی بَعَثَنِی بِالْحَقِّ نَبِیًّا وَاصْطَفَانِی بِالرِّسَالَةِ نَجِیًّا، مَا ذُکِرَ خَبَرُنَا هَذَا فِی مَحْفِلٍ مِنْ مَحَافِلِ أَهْلِ الْأَرْضِ، وَفِیهِ جَمْعٌ مِنْ شِیعَتِنَا وَمُحِبِّینَا، إِلاَّ وَنَزَلَتْ عَلَیْهِمُ الرَّحْمَةُ، وَحَفَّتْ بِهِمُ الْمَلائِکَةُ، وَاسْتَغْفَرَتْ لَهُمْ إِلَی أَنْ یَتَفَرَّقُوا.

فَقَالَ عَلِیٌّ عَلَیْهِ السَّلامُ: إِذًا وَاللَّهِ فُزْنَا وَفَازَ شِیعَتُنَا وَرَبِّ الْکَعْبَةِ.

فَقَالَتْ فَاطِمَةُ عَلَیْهَا السَّلامُ: یَا أَبَتَاهُ فَمَا لِمَنْ حَضَرَ مَعَنَا تَحْتَ الْکِسَاءِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ: وَالَّذِی بَعَثَنِی بِالْحَقِّ نَبِیًّا، لَوْ أَنَّ قَوْمًا اجْتَمَعُوا لِذِکْرِ هَذَا الْخَبَرِ الَّذِی جَرَی لَنَا أَهْلَ الْبَیْتِ وَلَیْسَ فِیهِمْ حُزْنٌ فَنَزَلَ عَلَیْهِمُ الْفَرَجُ، وَلا مَهْمُومٌ إِلاَّ وَأَذْهَبَ اللَّهُ هَمَّهُ، وَلا مَغْمُومٌ إِلاَّ وَکَشَفَ اللَّهُ غَمَّهُ، وَلا طَالِبَ حَاجَةٍ إِلاَّ وَقَضَی اللَّهُ حَاجَتَهُ.

فَقَالَتْ فَاطِمَةُ عَلَیْهَا السَّلامُ: یَا أَبَتَاهُ حَسْبُنَا مَا أَعْطَانَا اللَّهُ عَزَّ وَجَلَّ، فَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِینَ.
        """.trimIndent()
    )

    val all: List<ReligiousText> = listOf(ZIYARAT_ASHURA, SAHIFA_DUA_7, HADITH_KISA)

    fun byId(id: String): ReligiousText = all.first { it.id == id }
